const { email, firstName, lastName, phone, description } = $.input;

if (!email) throw new Error('email is required');

const values = {
  email_addresses: [{ email_address: email }]
};

if (firstName || lastName) {
  const name = {};
  if (firstName) name.first_name = firstName;
  if (lastName) name.last_name = lastName;
  values.name = [name];
}

if (phone) {
  values.phone_numbers = [{ original_phone_number: phone }];
}

if (description) {
  values.description = [{ value: description }];
}

return { values };

const resp = $.steps.upsertPerson.response || {};
const data = resp.data || {};
const id = data.id || {};

return {
  recordId: id.record_id || '',
  objectId: id.object_id || '',
  webUrl: data.web_url || '',
  createdAt: data.created_at || '',
  email: $.input.email,
  summary: id.record_id
    ? `Upserted person ${$.input.email} (${id.record_id})`
    : 'Failed to upsert person'
};
